    opts = opts || {}
    if (opts.availableSeats) { return ppCloneSeats(opts.availableSeats) }
    if (chamberId === 'executive') { return ppReadExecutiveSeats() }
    return ppReadDistrictSeats(districtId)
}

/** Seat pool for pro-democratic reform vote coalitions (home IGs' blocs excluded). */
function ppReformVoteAvailableSeats(districtId) {
    var seats = ppReadDistrictSeats(districtId)
    var homeIgs = ppHomeIgsForDistrict(districtId)
    var hasHomeCorp = false
    var hasHomeSynd = false
    for (var i = 0; i < homeIgs.length; i++) {
        if (PP_IG_KIND[homeIgs[i]] === 'corporate') { hasHomeCorp = true }
        if (PP_IG_KIND[homeIgs[i]] === 'syndicate') { hasHomeSynd = true }
    }
    if (hasHomeCorp) { seats.C = 0 }
    if (hasHomeSynd) { seats.G = 0 }
    seats.H = 0
    return seats
}

/** Attribute party seats to IGs for bandwidth billing (v1 heuristic). */
